setup.sql:
GRANT EXECUTE ON shop.* TO 'app'@'%';
DROP PROCEDURE IF EXISTS shop.undo_churn;
DROP PROCEDURE IF EXISTS shop.undo_churn_bulk;
DELIMITER //
CREATE PROCEDURE shop.undo_churn(n INT) SQL SECURITY INVOKER
BEGIN
  DECLARE i INT DEFAULT 0;
  WHILE i < n DO
    UPDATE shop.orders SET amount = amount + 1 WHERE id = {{base}} + (i % 500);
    DO SLEEP(0.05);
    SET i = i + 1;
  END WHILE;
END//
CREATE PROCEDURE shop.undo_churn_bulk(n INT) SQL SECURITY INVOKER
BEGIN
  DECLARE i INT DEFAULT 0;
  WHILE i < n DO
    UPDATE shop.orders SET amount = amount + 1 WHERE id = {{base}} + (i % 500);
    SET i = i + 1;
  END WHILE;
END//
DELIMITER ;
